<?php
namespace App\Services;
use App\Enums\{NavigationLinkType,NavigationMenuLocation}; use App\Models\{Category,CmsPage,NavigationMenu}; use Illuminate\Support\Facades\Cache;
class NavigationService {
 public const ROUTES=['home'=>'home','search'=>'storefront.search','sell'=>'vendor.apply','wishlist'=>'account.wishlist.index','cart'=>'cart.index'];
 public function menu(NavigationMenuLocation|string $location):array { $key='navigation.'.($location instanceof NavigationMenuLocation?$location->value:$location); return Cache::remember($key,60,function()use($location){$menu=NavigationMenu::where('location',$location instanceof NavigationMenuLocation?$location->value:$location)->where('is_active',true)->with('items')->first(); if(!$menu)return []; $items=$menu->items->where('is_active',true); $cats=Category::whereIn('id',$items->where('link_type',NavigationLinkType::Category)->pluck('reference_id'))->active()->get()->keyBy('id'); $pages=CmsPage::public()->whereIn('id',$items->where('link_type',NavigationLinkType::CmsPage)->pluck('reference_id'))->get()->keyBy('id'); return $items->map(function($i)use($cats,$pages){$type=$i->link_type; $url=match($type){NavigationLinkType::Route=>isset(self::ROUTES[$i->url])?route(self::ROUTES[$i->url]):null,NavigationLinkType::Category=>($c=$cats->get($i->reference_id))?route('storefront.categories.show',$c):null,NavigationLinkType::CmsPage=>($p=$pages->get($i->reference_id))?route('storefront.pages.show',$p->slug):null,NavigationLinkType::External=>preg_match('/^https:\/\//i',(string)$i->url)?$i->url:null}; $label=$type===NavigationLinkType::CmsPage&&isset($p)?$p->localized_title:$i->label; return $url?['label'=>$label,'url'=>$url,'external'=>$type===NavigationLinkType::External,'new_tab'=>$i->open_in_new_tab]:null;})->filter()->values()->all();}); }
 public function megaMenu(){return Cache::remember('navigation.mega_menu',60,fn()=>Category::roots()->active()->whereDoesntHave('parent',fn($q)=>$q->where('is_active',false))->with(['activeChildren'=>fn($q)=>$q->ordered()->limit(8)])->ordered()->limit(18)->get());}
 public function clear():void {foreach(['header','footer_shop','footer_help','footer_sellers','footer_company'] as $k)Cache::forget('navigation.'.$k); Cache::forget('navigation.mega_menu');}
}
